<?php $pageTitle='Admin Login';$cssPath='../css/style.css';$homePath='../index.php'; require '../db/connection.php'; require '../includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare('SELECT * FROM admins WHERE email=?');$st->execute([trim($_POST['email']??'')]);$admin=$st->fetch();if($admin&&password_verify($_POST['password']??'',$admin['password'])){session_regenerate_id(true);$_SESSION['admin']=['id'=>$admin['id'],'name'=>$admin['name']];redirect('dashboard.php');}$error='Incorrect admin credentials.';} include '../includes/header.php'; ?><div class="form-page"><div class="panel"><span class="eyebrow">Haven Hotel</span><h1>Admin login</h1><?php if(!empty($error)): ?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="button" type="submit">Enter dashboard</button></form></div></div><?php include '../includes/footer.php'; ?>
